import java.util.*;class RiverOxbowTest{public static void main(String[]a){var global=new EnvironmentMap(EnvironmentMap.filled(2048*2048,92));var w=new TerraForge.World(512,62,83);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(512*512,62);e.river=new float[512*512];e.material=new byte[512*512];e.snow=new float[512*512];var pond=new RiverRibbon.Oxbow(800,800,20,90,0);RiverRibbon.oxbow(global,w,512,512,62,pond);int wet=0;for(int i=0;i<w.height.length;i++)if(e.waterY(i,62)>Math.round(w.height[i])){wet++;if(e.river[i]!=0||w.height[i]<87)throw new AssertionError("Invalid oxbow bed");}if(wet<300||wet>900)throw new AssertionError("Missing horseshoe oxbow "+wet);Arrays.fill(global.height,130);Arrays.fill(w.height,130);Arrays.fill(e.water,62);RiverRibbon.oxbow(global,w,512,512,62,pond);for(float water:e.water)if(water!=62)throw new AssertionError("Oxbow carved through hillside");System.out.println("PASS: shallow horseshoe oxbow on low floodplain; rejects steep/high terrain");}}
